  const st = PROS_ST.includes(req.stage) && !['fail', 'pause'].includes(req.stage) ? req.stage : '';
  if (!st) return { ok: false, error: 'مرحله نامعتبر است.' };
  const pr = parse(o.pros, null) || { log: [], type: pr2TypeOf(o) }; pr.log = pr.log || []; pr.type = pr2Type(pr);
  if (pr.stage === 'pause' || pr.stage === 'fail') return { ok: false, error: pr.stage === 'pause' ? 'درمان پروتز متوقف است؛ اول «ادامه‌ی درمان» را بزنید.' : 'شکست ایمپلنت ثبت شده؛ مراحل بعد از کاشت دوباره شروع می‌شود.' };
  if (!pr2Path(pr.type).includes(st)) return { ok: false, error: 'این مرحله در مسیر «' + PR2_TL[pr.type] + '» نیست.' };
  if (pr.stage === st && !req.note && !req.rep) return { ok: true, pros: pr };
  if (pr.stage !== st) { delete pr.wait; if (st !== 'lab') delete pr.after; }
  if (st === 'done' && pr.repair) { pr.repairs = (pr.repairs || []).concat([Object.assign({}, pr.repair, { end: nowIso(), res: 'lab' })]).slice(-10); delete pr.repair; }
  pr.stage = st; pr.at = nowIso(); pr.log.push(Object.assign({ k: st, at: pr.at, by: tcut(req.by, 60), note: tcut(req.note, 300) }, req.rep ? { rep: 1 } : {})); pr.log = pr.log.slice(-60);
  const ops = [db.prepare('UPDATE plans SET pros=? WHERE id=?').bind(JSON.stringify(pr), o.id), bump(db)];
  if (st === 'done') {
    ops.push(db.prepare(`UPDATE labs SET st='done', upd=? WHERE plan=? AND st NOT IN ('done','cancel')`).bind(nowIso(), o.id), lbump(db));
    const has = await db.prepare(`SELECT id FROM tasks WHERE plan=? AND kind='recall' AND done=0`).bind(o.id).first();
    if (!has) ops.push(taskIns(db, o, 'recall', addMonths(6), 'چکاپ ۶ ماهه بعد از تحویل پروتز'));
    if (!(await db.prepare(`SELECT id FROM tasks WHERE plan=? AND kind='pweek' AND done=0`).bind(o.id).first())) ops.push(taskIns(db, o, 'pweek', addDays(7), 'تماس یک هفته بعد از تحویل پروتز'));
  }
  await db.batch(ops);
