  let it = null;
  if (req.item) it = await db.prepare('SELECT * FROM inv_items WHERE id=?').bind(String(req.item)).first();
  else if (req.spec) { const o = invSpec(req.spec), e = invValid(o); if (e) return { ok: false, error: e }; it = await invFind(db, req.spec); }
  if (!it) return { ok: false, error: 'این قلم در انبار پیدا نشد.' };
