  if (!isFinite(n) || n < 0 || n > 100000 || (type !== 'adj' && n === 0)) return { ok: false, error: 'تعداد را درست وارد کنید.' };
  const sup = req.sup ? await inv2Sup(db, req.sup) : null; if (req.sup && !sup) return { ok: false, error: 'تأمین‌کننده پیدا نشد.' };
