  const day = inv2Day(r.day); if (!day) return { ok: false, error: 'تاریخ رسید باید امروز یا حداکثر ۳۰ روز قبل باشد.' };
  let po = null; if (r.po) { po = await db.prepare('SELECT * FROM inv_po WHERE id=?').bind(tcut(r.po, 60)).first(); if (!po) return { ok: false, error: 'سفارش خرید پیدا نشد.' }; if (po.st === 'cancel' || po.st === 'received') return { ok: false, error: 'این سفارش خرید ' + (po.st === 'cancel' ? 'لغو شده' : 'کامل دریافت شده') + ' است.' }; }
