/* ---------- inv3: consignment (امانی), loans out, fixed assets (اموال ثابت), kits, general consumables, brand×size chart ---------- */
let INV3_INIT = false;
async function inv3Init(db) {
  if (INV3_INIT) return; INV3_INIT = true;
  await db.batch([
    db.prepare(`CREATE TABLE IF NOT EXISTS inv_asset (id TEXT PRIMARY KEY, no TEXT UNIQUE, cls TEXT, name TEXT, model TEXT, serial TEXT, loc TEXT, buyDay TEXT, price INTEGER, sup TEXT, st TEXT, note TEXT, at TEXT, by TEXT, upd TEXT, act INTEGER DEFAULT 1)`),
    db.prepare(`CREATE TABLE IF NOT EXISTS inv_asset_log (id TEXT PRIMARY KEY, asset TEXT, kind TEXT, day TEXT, note TEXT, cost INTEGER, who TEXT, by TEXT, at TEXT)`),
    db.prepare(`CREATE TABLE IF NOT EXISTS inv_kit (id TEXT PRIMARY KEY, name TEXT, parts TEXT, note TEXT, act INTEGER DEFAULT 1, at TEXT)`),
    db.prepare(`CREATE TABLE IF NOT EXISTS inv_kitlog (id TEXT PRIMARY KEY, kit TEXT, kind TEXT, plan TEXT, pname TEXT, asst TEXT, day TEXT, chk TEXT, missing TEXT, note TEXT, by TEXT, at TEXT, ref TEXT)`),
    db.prepare(`CREATE TABLE IF NOT EXISTS inv_loan (id TEXT PRIMARY KEY, item TEXT, n INTEGER, ret INTEGER DEFAULT 0, who TEXT, day TEXT, note TEXT, by TEXT, at TEXT, st TEXT)`),
    db.prepare(`CREATE TABLE IF NOT EXISTS inv_cset (id TEXT PRIMARY KEY, item TEXT, sup TEXT, n INTEGER, price INTEGER, day TEXT, note TEXT, by TEXT, at TEXT)`)]);
  for (const c of ['cq INTEGER DEFAULT 0', 'csup TEXT']) { try { await db.prepare('ALTER TABLE inv_items ADD COLUMN ' + c).run(); } catch (e) { } }
  for (const c of ['cu INTEGER DEFAULT 0', 'consign INTEGER DEFAULT 0', 'who TEXT']) { try { await db.prepare('ALTER TABLE inv_moves ADD COLUMN ' + c).run(); } catch (e) { } }
}
const INV3_READ = { list: 1, consign: 1, assets: 1, assetLog: 1, kits: 1, kitlog: 1, gen: 1, chart: 1, loans: 1 };
const I3_ASSET_ST = { ok: 'سالم / در حال استفاده', repair: 'در تعمیر', broken: 'خراب', retired: 'از رده خارج', sold: 'فروخته شده' };
