/* ---------- mgr2: management reports (manager only; counts and sums, no patient names) ---------- */
const MR_KINDS = ['funnel', 'conv', 'lost', 'times', 'monthly', 'svc', 'rev', 'paym', 'ar', 'chq', 'refund', 'settle', 'pl', 'svcrev', 'disc', 'imp', 'fail', 'prost', 'prosnow', 'lab', 'rpr', 'appt', 'heat', 'task', 'perf', 'att'];
