  const f = { at: now, by, teeth, note, months, cont: 1, stage: pr.stage };
  if (req.removed) { f.removed = now; const r = p5ReimpOps(db, o, pr, months, by, teeth); ops.push(...r.ops); f.due = r.due; }
  else ops.push(taskIns(db, o, 'pfail', tehranDay(), teeth.join(',')));
  if (pr.map) teeth.forEach(k => { if (pr.map[k]) { f.map = f.map || {}; f.map[k] = pr.map[k]; delete pr.map[k]; } });
  pr.fails = (pr.fails || []).concat([f]).slice(-10);
