    S.w.forEach(([id, name, proc, act, sort]) => ops.push(db.prepare('INSERT OR IGNORE INTO lab_wt (id,name,proc,active,sort) VALUES (?,?,?,?,?)').bind(id, name, proc || null, act ? 1 : 0, sort || 0)));
