  const [d, p, w, c, u] = await Promise.all([db.prepare('SELECT * FROM lab_dept ORDER BY sort, id').all(), db.prepare('SELECT * FROM lab_proc ORDER BY name').all(), db.prepare('SELECT * FROM lab_wt ORDER BY sort, id').all(), kvGet(db, 'l2colors'),
    db.prepare(`SELECT id, name, active, lab, CASE WHEN ph IS NOT NULL AND ph<>'' THEN 1 ELSE 0 END hp FROM users WHERE role='lab' ORDER BY name`).all()]);
