    ops.push(db.prepare(`UPDATE lab_step SET st='done', done_by=?, done_name=?, done_at=?, note=COALESCE(NULLIF(?,''),note) WHERE id=?`).bind(me.id, me.name, now, text, s.id));
    await db.batch(ops); const o2 = []; const cur = await l2SaveCur(db, l, d, o2, null);
    if (cur.all) { const lg = parse(l.log, []) || []; lg.push({ st: '', at: now, by: me.name, note: 'همه‌ی مراحل ساخت انجام شد؛ آماده‌ی ارسال', lab: 1 }); o2.push(db.prepare('UPDATE labs SET log=? WHERE id=?').bind(JSON.stringify(lg.slice(-80)), l.id)); }
