    if (!text) return { ok: false, error: 'دلیل برگشت را بنویسید.' };
    ops.push(await l2Ret(db, l, 'refresh', steps, s, text, me.name));
    steps.filter(x => x.idx >= s.idx && (x.part || '') === (s.part || '')).forEach(x => ops.push(db.prepare(`UPDATE lab_step SET st='pend', acc_by=NULL, acc_name=NULL, acc_at=NULL, done_by=NULL, done_name=NULL, done_at=NULL WHERE id=?`).bind(x.id)));
