    const tt = (p.teeth || []).filter(k => !billed.has(k)); if (!ex && billed.size && !tt.length) continue;
    const pr = await l5Price(db, l, Object.assign({}, d, { teeth: tt, wtid: p.wtid || d.wtid }), acct, A); if (p.label) pr.lines.forEach(x => { x.t += ' — ' + p.label; });
