    const mat = ex ? Number(ex.mat) || 0 : 0, dpct = ex ? Number(ex.dpct) || 0 : 0, sum = pr.lines.reduce((s, x) => s + x.amt, 0) + mat, disc = Math.round(sum * dpct / 100), vat = Math.round((sum - disc) * (Number(S.vat) || 0) / 100);
