  if (req.lid) { const l = await db.prepare('SELECT plan FROM labs WHERE id=?').bind(String(req.lid)).first(); return l ? l.plan : ''; }
  if (req.rid) { const x = await db.prepare('SELECT plan FROM refunds WHERE id=?').bind(String(req.rid)).first(); return x ? x.plan : ''; }
  if (req.fid) { const f = await db.prepare('SELECT plan FROM files WHERE id=?').bind(String(req.fid)).first(); return f ? f.plan : ''; }
  if (req.eid) { const e = await db.prepare('SELECT plan FROM events WHERE id=?').bind(String(req.eid)).first(); return e ? e.plan : ''; }
