async function once(db, sendId, fn, act) {
  sendId = tcut(sendId, 80);
  if (!sendId) return fn();
  const k = 'sid:' + (act ? act + ':' : '') + sendId;
  if (Math.random() < 0.02) await db.prepare(`DELETE FROM kv WHERE k LIKE 'sid:%' AND t < ?`).bind(Date.now() - 30 * 864e5).run();
  const ins = await db.prepare('INSERT OR IGNORE INTO kv (k,v,t) VALUES (?,?,?)').bind(k, '{"pending":1}', Date.now()).run();
  if (!ins.meta.changes) {
    let row = null;
    for (let i = 0; i < 16; i++) {
      row = await db.prepare('SELECT v,t FROM kv WHERE k=?').bind(k).first();
      if (!row) break;
      const r0 = parse(row.v, {});
      if (!r0.pending) return r0;
      if (Date.now() - row.t > 60000) break;               // abandoned attempt: run again
      await new Promise(z => setTimeout(z, 500));
    }
    if (row && Date.now() - row.t <= 60000) return { ok: false, error: 'هنوز در حال انجام است؛ کمی بعد دوباره تلاش می‌شود.' };
    await kvSet(db, k, '{"pending":1}').run();
  }
  let r;
  try { r = await fn(); } catch (e) { await db.prepare('DELETE FROM kv WHERE k=?').bind(k).run(); throw e; }
  if (r && r.ok) await kvSet(db, k, JSON.stringify(r)).run(); else await db.prepare('DELETE FROM kv WHERE k=?').bind(k).run();
  return r;
}
