/* -- win-back: patients who drifted away -- */
async function winback(db) {
  const td = tehranDay(), now = nowIso(), y1 = new Date(Date.now() - 365 * 864e5).toISOString(), d30 = new Date(Date.now() - 30 * 864e5).toISOString();
  const [pl, rc, sn] = await db.batch([
    db.prepare(`SELECT id, name, status, queue, data, lost, doneAt, updatedAt, surgN, pros FROM plans WHERE ? <> '' AND (queue IN ('undecided','lost') OR (status IN ('confirmed','modified') AND (queue IS NULL OR queue IN ('','done')) AND COALESCE(surgN,0)=0) OR (pros IS NOT NULL AND pros<>''))`).bind(y1),
    db.prepare(`SELECT t.plan, t.name, t.phone, t.due FROM tasks t WHERE t.kind='recall' AND t.done=0 AND t.due < ?`).bind(addDays(-14)),
    db.prepare(`SELECT plan, kind, until FROM wb WHERE until > ?`).bind(now)]);
  const skip = new Set(sn.results.map(x => x.plan + '|' + x.kind)), out = [], BUSY = await pr2Busy(db, td);
  const add = (kind, o, since, info, phone) => { if (!skip.has(o.id + '|' + kind)) out.push({ kind, id: o.id, name: o.name || '', phone: phone || '', since: since || '', info: info || '' }); };
  for (const o of pl.results) {
    const h = (parse(o.data, {}).h) || {};
    if (o.queue === 'undecided' || o.queue === 'lost') { const l = parse(o.lost, {}) || {}; add('lost', o, l.at || o.updatedAt, l.cr || l.r || '', h.phone); continue; }
    const pr = parse(o.pros, null);
    if (pr && pr.stage === 'pause') { if (pr.pause && pr.pause.stop) add('pros', o, pr.pause.stop, 'pause', h.phone); continue; }
    if (pr && pr.stage === 'fail') continue;
    if (pr && pr.stage && pr.stage !== 'done' && BUSY.has(o.id)) continue;
    if (pr && pr.stage && pr.stage !== 'done') { const at = pr.at || '', late = pr.stage === 'heal' ? (pr.ready && pr.ready < addDays(-30)) : (at && at < new Date(Date.now() - 45 * 864e5).toISOString()); if (late) add('pros', o, pr.stage === 'heal' ? pr.ready : at, pr.stage, h.phone); continue; }
    if ((o.status === 'confirmed' || o.status === 'modified') && !Number(o.surgN) && (o.doneAt || o.updatedAt) < d30) add('nosurg', o, o.doneAt || o.updatedAt, '', h.phone);
  }
  for (const t of rc.results) if (!skip.has(t.plan + '|recall')) out.push({ kind: 'recall', id: t.plan, name: t.name || '', phone: t.phone || '', since: t.due, info: '' });
  out.sort((a, b) => String(b.since).localeCompare(String(a.since)));
  return { ok: true, items: out.slice(0, 5000), total: out.length, today: td };
}
async function wbSnooze(db, req) {
  const kind = ['lost', 'nosurg', 'recall', 'pros'].includes(req.kind) ? req.kind : ''; if (!kind) return { ok: false, error: 'نوع نامعتبر' };
  const days = Math.max(1, Math.min(3650, Number(req.days) || 30)), until = new Date(Date.now() + days * 864e5).toISOString();
  await db.prepare('INSERT OR REPLACE INTO wb (id,plan,kind,until,note,by,at) VALUES (?,?,?,?,?,?,?)').bind(tcut(req.id, 60) + '|' + kind, tcut(req.id, 60), kind, until, tcut(req.note, 300), tcut(req.by, 60), nowIso()).run();
  return { ok: true };
}
