const ROLE_FA = { doctor: 'پزشک', consultant: 'مشاور', staff: 'پذیرش', surgery: 'دستیار جراحی', lab: 'لابراتوار', inventory: 'انبار', manager: 'مدیر' };
/* -- performance per person (from the change log) and per doctor (from plans) -- */
async function perf(db, req) {
  const from = isDay(req.from) ? req.from : addDays(-30), to = isDay(req.to) ? req.to : tehranDay(), a = tehStart(from), b = tehStart(addDays(1, to));
  const [au, pl, ap] = await db.batch([
    db.prepare(`SELECT user, role, action, info FROM audit WHERE at>=? AND at<?`).bind(a, b),
    db.prepare(`SELECT status, total, data, createdAt FROM plans WHERE createdAt>=? AND createdAt<?`).bind(a, b),
    db.prepare(`SELECT by, st FROM appts WHERE day>=? AND day<=? AND st IN ('done','noshow','set')`).bind(from, to)]);
  const P = {};
  for (const r of au.results) { const k = r.user || ('رمز مشترک ' + (ROLE_FA[r.role] || r.role)), x = P[k] = P[k] || { name: k, role: r.role, n: 0, acts: {}, pay: 0 }; x.n++; x.acts[r.action] = (x.acts[r.action] || 0) + 1; if (r.action === 'payAdd') { const s = parse(r.info, {}); x.pay += Number(s.pay && s.pay.amount) || 0; } }
  for (const r of ap.results) { const k = r.by || ''; if (!k || !P[k]) continue; const x = P[k]; x.ap = x.ap || { done: 0, noshow: 0 }; if (r.st === 'done') x.ap.done++; if (r.st === 'noshow') x.ap.noshow++; }
  const D = {};
  for (const o of pl.results) { const doc = ((parse(o.data, {}).h) || {}).doc || 'نامشخص', x = D[doc] = D[doc] || { doc, plans: 0, conf: 0, value: 0 }; x.plans++; if (o.status === 'confirmed' || o.status === 'modified') { x.conf++; x.value += Number(o.total) || 0; } }
  return { ok: true, from, to, people: Object.values(P).sort((x, y) => y.n - x.n), docs: Object.values(D).sort((x, y) => y.plans - x.plans) };
}
