  if (!isDay(d.day)) return { error: 'تاریخ سند نامعتبر است.' };
  if (!d.sync && set.lockDay && d.day <= set.lockDay) return { error: 'این دوره بسته شده است؛ تاریخ سند باید بعد از ' + set.lockDay + ' باشد.' };
