async function finInvCalc(db, x) {
  const [sv, pe, fe] = await db.batch([db.prepare('SELECT * FROM fin_svc'), db.prepare('SELECT * FROM fin_payee'), db.prepare('SELECT * FROM fin_fee')]);
  const S = {}, P = {}, F = {}; sv.results.forEach(s => S[s.id] = s); pe.results.forEach(p => P[p.id] = p); fe.results.forEach(f => F[f.svc + '|' + f.payee] = f.amount);
  const lines = []; let err = '';
  for (const l of (Array.isArray(x.lines) ? x.lines : []).slice(0, 80)) {
    const s = S[l.svc], q = Math.max(0, Math.min(999, Number(String(l.qty).replace(/[^\d.]/g, '')) || 0)); if (!s || !q) continue;
    const p = P[l.payee] || null; if (s.rule !== 'clinic' && !p) { err = 'برای «' + s.name + '» پزشک یا همکار را انتخاب کنید.'; break; }
    if (s.rule === 'clinic' && !l.init) { err = 'برای «' + s.name + '» پزشک اولیه را انتخاب کنید.'; break; }
    const price = l.price !== undefined && l.price !== '' ? pAmt(l.price) : s.price, amt = l.amtFix !== undefined && l.amtFix !== '' && l.amtFix !== null ? pAmt(l.amtFix) : Math.round(price * q);
    const fee0 = l.fee0 ? 1 : 0, fx = l.feeFix !== undefined && l.feeFix !== '' && l.feeFix !== null ? pAmt(l.feeFix) : null, clin = !p || p.kind === 'clinic';
    const fee = fee0 || clin ? 0 : fx !== null ? fx : Math.round((F[s.id + '|' + p.id] || 0) * q);
    const ln = { svc: s.id, name: s.name, cat: s.cat, qty: q, price, amt, payee: p ? p.id : '', pname: p ? p.name : 'کلینیک', fee, fee0, why: tcut(l.why, 160), init: tcut(l.init, 40), initName: P[l.init] ? P[l.init].name : '' };
    if (fx !== null && clin) ln.xfee = fx; /* the Excel's «مبلغ کل» of a clinic row: report only, no journal */
    lines.push(ln);
  }
  if (err) return { err };
  const total = lines.reduce((a, l) => a + l.amt, 0), discC = pAmt(x.discC), parts = pAmt(x.parts), feeSum = lines.reduce((a, l) => a + l.fee, 0);
  let discD = pAmt(x.discD); if (discD > feeSum) return { err: 'تخفیف سهم پزشک بیشتر از جمع سهم پزشکان در این صورتحساب است.' };
  if (discC + discD > total) return { err: 'جمع تخفیف‌ها بیشتر از هزینه‌ی خدمات است.' };
  let left = discD; lines.forEach((l, i) => { const share = feeSum ? (i === lines.length - 1 ? left : Math.round(discD * l.fee / feeSum)) : 0; l.feeNet = l.fee - Math.min(share, l.fee); left -= Math.min(share, l.fee); });
  return { lines, total, discC, discD, parts, net: total - discC - discD + parts, fees: lines.reduce((a, l) => a + l.feeNet, 0) };
}
