  const fee = {}; c.lines.forEach(l => { if (l.feeNet > 0) fee[l.payee] = (fee[l.payee] || 0) + l.feeNet; });
  Object.keys(fee).forEach(pid => { const nm = (c.lines.find(l => l.payee === pid) || {}).pname || ''; L.push({ acc: '5101', dr: fee[pid], party: 'd:' + pid, pname: nm }, { acc: '2103', cr: fee[pid], party: 'd:' + pid, pname: nm }); });
