  await db.batch([...(o.doc ? finVoidOps(db, o.doc, req.by, req.note) : []), db.prepare(`UPDATE fin_inv SET st='void', note=COALESCE(note,'')||' — باطل: '||? WHERE id=?`).bind(tcut(req.note, 200), o.id)]);
