  const { results } = await db.prepare(`SELECT party, MAX(pname) pname, SUM(dr) dr, SUM(cr) cr, MAX(day) last FROM fin_line WHERE live=1 AND acc=? AND day<=? AND party<>'' GROUP BY party`).bind(acc, to).all();
