    await finInit(db); await xl3Init(db);
    if (!isDay(day)) day = tehranDay();
    const o = await getRow(db, plan); if (!o) return; await xlFileNo(db, o);
    const sug = await finSuggest(db, { id: plan, day }); if (!sug || !sug.ok) return;
