    const lines = (sug.lines || []).filter(l => l.qty > 0).map(l => ({ svc: l.svc, payee: l.payee || (clinic ? clinic.id : ''), qty: l.qty, price: '', init: l.init || l.payee || (clinic ? clinic.id : ''), fee0: l.fee0, why: (l.why || '') + (l.payee ? '' : ' · پزشک مشخص نشد') }));
    const ex = (await db.prepare(`SELECT id, by, discC, discD, parts, note, pfile FROM fin_inv WHERE plan=? AND day=? AND st='ok' ORDER BY no`).bind(plan, day).all()).results;
