    if (human) return;
    if (!lines.length) { if (auto) await db.batch([db.prepare(`UPDATE fin_inv SET st='void', note=COALESCE(note,'')||' — باطل: کارهای روز حذف شد' WHERE id=?`).bind(auto.id), ...((await db.prepare('SELECT doc FROM fin_inv WHERE id=?').bind(auto.id).first()).doc ? finVoidOps(db, (await db.prepare('SELECT doc FROM fin_inv WHERE id=?').bind(auto.id).first()).doc, 'خودکار', 'کارهای روز حذف شد') : [])]); return; }
    const d = parse(o.data, {}) || {}, h = d.h || {};
    const r = await finInvSave(db, { by: 'خودکار', inv: { id: auto ? auto.id : '', day, plan, lines, discC: auto ? auto.discC : 0, discD: auto ? auto.discD : 0, parts: auto ? auto.parts : 0, pays: [], note: auto ? auto.note : 'ثبت خودکار از کارهای روز', pfile: auto ? auto.pfile : (h.file || ''), nid: o.nid || h.nid || '', phone: h.phone || '' } }, 'accountant');
