/* ---- fx1: file number after surgery, notes on every stage, archive of paper files ---- */
const FX_ST = { reg: 'پذیرش', plan: 'طرح درمان', cons: 'مشاوره', surg: 'جراحی', sut: 'بخیه و ترخیص', unc: 'آنکاوری', impr: 'قالب‌گیری', lab: 'لابراتوار', try: 'امتحان پروتز', deliv: 'تحویل پروتز', chk: 'چکاپ و پیگیری', arc: 'بایگانی (پرونده‌ی کاغذی)', other: 'سایر' };
