    if (s === 'done') return 'chk'; if (s === 'deliv') return 'deliv'; if (['rabt', 'frame', 'bite', 'tryin', 'jig'].includes(s)) return 'try'; if (s === 'lab') return 'lab'; if (s === 'impr') return 'impr';
