  if (!FX_W[role]) return { ok: false, error: 'با این ورود فقط می‌توانید توضیحات را ببینید.' };
  const who = tcut(req.by, 60) || '', now = nowIso();
  if (op === 'del') {
    const n = await db.prepare('SELECT id FROM fx_note WHERE id=? AND plan=? AND del=0').bind(tcut(req.nid, 60), o.id).first(); if (!n) return { ok: false, error: 'این توضیح پیدا نشد.' };
    await db.prepare('UPDATE fx_note SET del=1, upd=?, updBy=? WHERE id=?').bind(now, who, n.id).run();
    return { ok: true, id: o.id };
  }
  const kind = req.kind === 'pen' ? 'pen' : 'text', text = tcut(req.text, kind === 'pen' ? 300 : 4000), img = kind === 'pen' ? String(req.img || '') : '';
  if (kind === 'pen' && !(img.length < 700000 && /^data:image\/(png|jpeg);base64,[A-Za-z0-9+/=]+$/.test(img))) return { ok: false, error: 'نوشته‌ی دستی ذخیره نشد؛ دوباره بنویسید.' };
  if (kind === 'text' && !text) return { ok: false, error: 'متن توضیح خالی است.' };
