    const sg0 = parse(o.surg, null), keep = ((sg0 && sg0.sessions) || []).filter(x => x && !x.arc); /* sessions done later on the site stay */
    let sg = surg ? Object.assign({}, sg0 || {}, keep.length ? { sessions: surg.sessions } : surg, { dis: (sg0 && sg0.dis) || surg.dis }) : (keep.length ? Object.assign({}, sg0) : null);
    if (sg) { sg.sessions = (surg ? surg.sessions : []).concat(keep).map((x, i) => Object.assign(x, { n: i + 1 })); if (keep.length) sg.lastDay = [sg.lastDay || '', ...keep.map(x => tehranDay(x.at))].sort().pop(); }
    await db.batch([db.prepare('UPDATE plans SET name=?, nid=?, data=?, surg=?, surgN=?, updatedAt=? WHERE id=?').bind(h.name, h.nid, JSON.stringify(d), sg ? JSON.stringify(sg) : '', sg ? (sg.sessions || []).length : 0, now, o.id), bump(db), ...(await fileOps())]);
