/* ---- fx2: forgotten (paper) files carry dated visits with cost and payments ---- */
const FX2_M = { cash: 'نقد', card: 'کارت', bank: 'واریز بانکی', chq: 'چک' };
function fx2PayOps(db, o, visits, who, now) {
  const ops = [db.prepare("UPDATE pays SET st='del', upd=? WHERE plan=? AND kind='arc' AND st<>'del'").bind(now, o.id)];
  (visits || []).forEach(v => { if (!(v.paid > 0)) return;
    ops.push(db.prepare('INSERT INTO pays (id,plan,name,kind,part,amount,due,no,bank,st,at,by,note,upd,pos) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')
      .bind(uuid(), o.id, o.name || '', 'arc', 's', v.paid, '', v.no || '', FX2_M[v.method] || '', 'ok', v.day + 'T08:30:00.000Z', who, tcut('پرداخت قبلی (' + (FX2_M[v.method] || '') + ')' + (v.svc ? ' — ' + v.svc : '') + (v.note ? ' — ' + v.note : ''), 300), now, '')); });
  ops.push(bump(db));
  return ops;
}

/* ---- fx3: payment gate (warning + logged reason + collection task), payment fixes ---- */
