/* ---- fx4: one balance for every place (file, debtors / creditors, gate, refund cap), approvals, refunds, cheques ---- */
const FX4_ACK = { staff: 1, consultant: 1, manager: 1 };
const FX4_MONEYR = { staff: 1, consultant: 1, manager: 1, accountant: 1 };
const FX4_TREATQ = ['surgdone', 'surgpart'];
