  for (const p of pays || []) { const a = Number(p.amount) || 0; if (p.st === 'ok') { ok += a; if (p.kind === 'arc') arcOk += a; } else if (p.st === 'wait' && p.kind === 'chq') wait += a; else if (p.st === 'bounce') bounce += a; }
