  const paid = ok - rfPaid, rest = total - paid - wait;
  return { total, paid, wait, bounce, rest, credit: hold ? 0 : Math.max(0, paid - total - rfOpen), rfOpen, rfPaid, diff, waived, treated: tr ? 1 : 0, hold: hold ? 1 : 0, lost: lost ? 1 : 0, arcOk };
