  if (!(await db.prepare("SELECT id FROM tasks WHERE plan=? AND kind='collect' AND done=0").bind(o.id).first())) ops.push(taskIns(db, o, 'collect', tehranDay(), tcut(FX3_SL[step] + ' با ' + ux2N(short) + ' تومان مانده — ' + why, 300)));
  ops.push(bump(db)); await db.batch(ops);
