  await db.batch([kvSet(db, 'fx4ok:' + o.id + ':' + step, JSON.stringify({ at: nowIso(), why })), closeTasks(db, o.id, ['payok'], 'ادامه تأیید شد: ' + why), bump(db)]);
  return { ok: true, short };
