  if (r.data && typeof r.data === 'object') { r.data = Object.assign({}, r.data); delete r.data.parts; delete r.data.fx4chg; delete r.data.ctot; if (r.data.arc && typeof r.data.arc === 'object') { r.data.arc = Object.assign({}, r.data.arc); delete r.data.arc.vt; if (Array.isArray(r.data.arc.visits)) r.data.arc.visits = r.data.arc.visits.map(v => Object.assign({}, v, { cost: 0, paid: 0 })); } }
  if (r.surg && typeof r.surg === 'object') { r.surg = Object.assign({}, r.surg); FX4_SGM.forEach(k => delete r.surg[k]); }
  if (Array.isArray(r.tasks)) r.tasks = r.tasks.map(t => ['collect', 'paylost', 'payok'].includes(t.kind) ? Object.assign({}, t, { info: '' }) : t);
