  const nv = (Array.isArray(a.visits) ? a.visits : []).slice(0, 100).filter(x => x && typeof x === 'object' && isDay(x.day) && x.day <= td).map(x => ({ day: x.day, cost: fx2amt(x.cost), paid: fx2amt(x.paid), method: FX2_M[x.method] ? x.method : 'cash' }));
