  B.forEach(k => { if (cnt[k]) cnt[k]--; else ch.push(k); }); Object.keys(cnt).forEach(k => { for (let i = 0; i < cnt[k]; i++) ch.push(k); });
  if (!ch.length) return { o, changed: 0 };
  const set = await finSet(db); if (set.lockDay && (ch.some(k => k.split('|')[0] <= set.lockDay) || ov.concat(nv).some(v => v.day <= set.lockDay))) return { error: 'مبلغ مراجعه‌های قبل از ' + set.lockDay + ' (دوره‌ی بسته‌شده‌ی حسابداری) تغییر نمی‌کند؛ با حسابدار هماهنگ کنید.' };
