const OC_ACTIONS = { ping: 1, oc: 1 };
ACC_ACTIONS.oc = 1;
const OC_SVC0 = [['imp', 'IMP'], ['gbr', 'GBR'], ['hard', 'نسج سخت'], ['ext', 'ext عقل'], ['ridge', 'ریج اسپلیت'], ['open', 'OPEN'], ['close', 'CLOSE']];
const OC_SEED = [
  ['orc', 'ارکیده', [50000000, 25000000, 0, 50000000, 80000000, 70000000, 50000000], [], 397000000],
  ['taj', 'تاج', [60000000, 30000000, 27000000, 70000000, 60000000, 60000000, 40000000], [], 9891532000],
  ['rsh', 'روشن‌طلب', [60000000, 40000000, 27000000, 70000000, 60000000, 60000000, 40000000], [['impr', 'قالبگیری', 50000000]], 4517000000],
  ['bsr', 'کلینیک باصری', null, [], 0],
  ['uni', 'کلینیک دانشگاه', null, [], 0]];
const OC_KIND = { tr: 'انتقال به حساب', pour: 'واریز به پور', chq: 'چک', cash: 'نقد' };
let OC_READY = false;
async function ocInit(db) {
  if (OC_READY) return;
  await db.batch([
    db.prepare(`CREATE TABLE IF NOT EXISTS oc_clinic (id TEXT PRIMARY KEY, name TEXT, ord INTEGER, active INTEGER DEFAULT 1, svc TEXT, ob INTEGER DEFAULT 0, obDay TEXT, upd TEXT, by TEXT)`),
    db.prepare(`CREATE TABLE IF NOT EXISTS oc_work (id TEXT PRIMARY KEY, clinic TEXT, day TEXT, patient TEXT, items TEXT, amount INTEGER, note TEXT, at TEXT, by TEXT, upd TEXT, st TEXT DEFAULT 'ok')`),
    db.prepare(`CREATE TABLE IF NOT EXISTS oc_pay (id TEXT PRIMARY KEY, clinic TEXT, day TEXT, kind TEXT, amount INTEGER, due TEXT, no TEXT, bank TEXT, cst TEXT, note TEXT, at TEXT, by TEXT, upd TEXT, st TEXT DEFAULT 'ok')`),
    db.prepare(`CREATE INDEX IF NOT EXISTS oc_work_day ON oc_work(day)`),
    db.prepare(`CREATE INDEX IF NOT EXISTS oc_pay_day ON oc_pay(day)`)]);
  if (!(await kvGet(db, 'oc:seed1'))) {
    const n = await db.prepare('SELECT COUNT(*) n FROM oc_clinic').first('n');
    if (!n) {
      const day = tehranDay(), now = nowIso();
      await db.batch(OC_SEED.map(([id, name, pr, extra, ob], i) => db.prepare('INSERT OR IGNORE INTO oc_clinic (id,name,ord,active,svc,ob,obDay,upd,by) VALUES (?,?,?,?,?,?,?,?,?)')
        .bind(id, name, i + 1, 1, JSON.stringify(OC_SVC0.map(([k, l], j) => ({ k, n: l, p: pr ? pr[j] : 0 })).concat(extra.map(([k, l, p]) => ({ k, n: l, p })))), ob, ob ? day : '', now, 'از اکسل «کارکرد کل سایر»')));
    }
    await kvSet(db, 'oc:seed1', nowIso()).run();
  }
  OC_READY = true;
}
const ocAmt = v => { const n = Math.round(Number(toEnD(String(v ?? '')).replace(/[,\s٬،]/g, ''))); return Number.isFinite(n) && n >= 0 && n <= 1e13 ? n : NaN; };
