    if (!L.some(x => x.id === String(p.clinic || ''))) return { ok: false, error: 'کلینیک را انتخاب کنید.' };
    const day = ocDay(p.day); if (!day) return { ok: false, error: 'تاریخ درست نیست.' };
    const kind = OC_KIND[p.kind] ? String(p.kind) : ''; if (!kind) return { ok: false, error: 'نوع دریافت را انتخاب کنید.' };
    const amount = ocAmt(p.amount); if (!Number.isFinite(amount) || amount <= 0) return { ok: false, error: 'مبلغ را درست بنویسید.' };
    const due = kind === 'chq' ? ocDay(p.due) : ''; if (kind === 'chq' && !due) return { ok: false, error: 'تاریخ سررسید چک را بنویسید.' };
    const id = ocId(p.id, 'p'), old = await db.prepare('SELECT * FROM oc_pay WHERE id=?').bind(id).first();
