    const no = kind === 'chq' ? tcut(String(p.no || '').trim(), 40) : '', bank = kind === 'chq' ? tcut(String(p.bank || '').trim(), 40) : '', note = tcut(String(p.note || '').trim(), 400);
    const cst = kind === 'chq' ? (old && old.kind === 'chq' ? old.cst || 'wait' : 'wait') : '';
