  const plans = pl.results.map(o => {
    const d = parse(o.data, {}), h = d.h || {}, sg = parse(o.surg, null) || {}, pr = parse(o.pros, null) || {}, lost = parse(o.lost, null);
    const imp = (sg.sessions || []).reduce((a, s) => a + Object.keys(s.imp || {}).length, 0);
    return [si(o.status), si(o.createdAt || ''), si(o.doneAt || ''), Number(o.total) || 0, si(d.brand || ''), si(h.doc || ''), si(h.ref || ''), si(h.city || ''), Number(o.surgN) || 0, si(pr.stage || ''), si(((sg.sessions || [])[0] || {}).savedAt || ''), imp, Number(sg.diff) || 0, si(lost ? (lost.cr || lost.r || '') : ''), si(lost ? lost.at : '')];
  });
