  if (req.total != null && d.brand && d.brand !== 'ref') { const t = N(req.total), S0 = N(req.parts && req.parts.S), P0 = N(req.parts && req.parts.P); if ([t, S0, P0].every(v => Number.isFinite(v) && v >= 0 && v < 1e13) && t) { total = t; if (S0 + P0 > 0) { const s2 = Math.round(S0 * t / (S0 + P0)); d.parts = { S: s2, P: t - s2 }; } if (pl10Opt3(d) && req.cash != null) { const c = N(req.cash); if (Number.isFinite(c) && c >= 0) d.pay.cash = String(c); } } }
