/* ---- a17 (owner 2026-11-10): paper-file (archive) implants consume stock — every implant line of a paper file takes one fixture out of inventory, like the surgery page. A ledger in kv (a17:<plan>) keeps the consumed keys so edits only add/return the difference. */
function a17Keys(sg) {
  const out = {}; const S = (sg && Array.isArray(sg.sessions)) ? sg.sessions : [];
  for (const ses of S) { if (!ses || !ses.arc) continue; const day = String(ses.at || '').slice(0, 10) || tehranDay();
    for (const k of Object.keys(ses.imp || {}).slice(0, 40)) { const m = ses.imp[k] || {};
      if (m.b && m.d && m.l && m.src !== 'loan') out[['fix', day, k, nrm(m.b), nrm(m.sys || ''), nnum(m.d), nnum(m.l)].join('|')] = { kind: 'fix', b: m.b, sys: m.sys || '', d: m.d, l: m.l, k, day };
      /* healing / cover caps are not consumed for paper files (the paper editor has no such fields; v3 files defaulted ht to heal) */ } }
  return out;
}
