  for (const key of Object.keys(want)) { if (led[key]) continue; const w = want[key]; const it = await invFind(db, { kind: w.kind, b: w.b, sys: w.sys, d: w.d, l: w.l || '' });
    ops.push(...invMoveOps(db, it.id, -1, 'use', by, 'پرونده‌ی کاغذی — دندان ' + tcut(w.k, 4), o.id, o.name, { day: w.day })); led[key] = it.id; n++; }
  for (const key of Object.keys(led)) { if (want[key]) continue;
    ops.push(...invMoveOps(db, led[key], 1, 'ret', by, 'پرونده‌ی کاغذی — حذف کاشت از پرونده (برگشت به انبار)', o.id, o.name, {})); delete led[key]; n++; }
